//! Port of the sprite replacement in `net.runelite.client.plugins.interfacestyles.InterfaceStylesPlugin`
//! (BSD-2, see `NOTICE`).
//!
//! The source reads `<skin>/<spriteId>.png` for every `SpriteOverride` row that lists the configured skin
//! and puts it in `Client.getSpriteOverrides()`. Here the same table (generated by
//! `tools/builtin-plugins/interfacestyles_sprites.py`) is decoded once per skin and returned as
//! `PluginOutput::sprite_overrides`; the shell swaps them into the interface sprites it draws and
//! restores the cache sprites when the list goes away.
//!
//! Not ported: widget overrides (the 2005 side-stone frames, which replace sprites by widget rather than
//! by sprite id), HD health bars, the 2010 menu and menu alpha, `RuneScape` cross sprites, always-stack
//! stones and condensed player options. They need widget-level sprite overrides, the health bar and menu
//! renderers, cross sprites and the menu model, none of which the client exposes yet.

use crate::NativePlugin;
use rustclient_plugin_api::{PluginOutput, SpriteOverride};
use rustclient_plugin_host::{PluginCall, PluginFault};
use std::sync::Arc;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Skin {
    Around2005,
    Around2006,
    Around2010,
}

impl Skin {
    /// The `gameframe` setting value, `None` for the default (no overrides).
    fn parse(choice: &str) -> Option<Self> {
        match choice {
            "AROUND_2005" => Some(Self::Around2005),
            "AROUND_2006" => Some(Self::Around2006),
            "AROUND_2010" => Some(Self::Around2010),
            _ => None,
        }
    }
}

/// One replacement sprite of one skin.
pub(crate) struct Entry {
    pub skin: Skin,
    pub sprite: u32,
    pub png: &'static [u8],
}

#[derive(Default)]
pub(crate) struct InterfaceStyles {
    /// The decoded overrides of the last configured skin, shared so repeat updates are cheap.
    cached: Option<(Skin, Vec<SpriteOverride>)>,
}

/// Decode the table rows of `skin`; a PNG that fails to decode is skipped, not fatal.
fn decode(skin: Skin) -> Vec<SpriteOverride> {
    crate::interfacestyles_sprites::SPRITES
        .iter()
        .filter(|entry| entry.skin == skin)
        .filter_map(|entry| {
            let image = image::load_from_memory_with_format(entry.png, image::ImageFormat::Png)
                .ok()?
                .into_rgba8();
            Some(SpriteOverride {
                sprite: entry.sprite,
                width: u16::try_from(image.width()).ok()?,
                height: u16::try_from(image.height()).ok()?,
                rgba: Arc::from(image.into_raw()),
            })
        })
        .collect()
}

impl NativePlugin for InterfaceStyles {
    fn output(&mut self, call: &mut PluginCall<'_>) -> Result<PluginOutput, PluginFault> {
        let Some(skin) = Skin::parse(call.config.choice("gameframe")) else {
            self.cached = None;
            return Ok(PluginOutput::default());
        };
        if self.cached.as_ref().map(|(cached, _)| *cached) != Some(skin) {
            self.cached = Some((skin, decode(skin)));
        }
        Ok(PluginOutput {
            sprite_overrides: self
                .cached
                .as_ref()
                .map(|(_, overrides)| overrides.clone())
                .unwrap_or_default(),
            ..PluginOutput::default()
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::interfacestyles_sprites::SPRITES;

    #[test]
    fn every_embedded_png_decodes_within_the_host_limits() {
        for skin in [Skin::Around2005, Skin::Around2006, Skin::Around2010] {
            let expected = SPRITES.iter().filter(|entry| entry.skin == skin).count();
            let decoded = decode(skin);
            assert_eq!(decoded.len(), expected, "{skin:?}: a PNG failed to decode");
            let bytes: usize = decoded.iter().map(|sprite| sprite.rgba.len()).sum();
            assert!(bytes <= rustclient_plugin_api::limits::SPRITE_OVERRIDE_BYTES);
            assert!(decoded.iter().all(|sprite| {
                sprite.width <= rustclient_plugin_api::limits::SPRITE_EDGE
                    && sprite.height <= rustclient_plugin_api::limits::SPRITE_EDGE
                    && sprite.rgba.len()
                        == usize::from(sprite.width) * usize::from(sprite.height) * 4
            }));
        }
    }

    #[test]
    fn the_table_has_unique_sprites_per_skin() {
        let mut seen = std::collections::BTreeSet::new();
        for entry in &SPRITES {
            let key = (entry.skin as u8, entry.sprite);
            assert!(seen.insert(key), "duplicate {key:?}");
        }
    }
}
